assert flatten_dict({'a':1,'b':{'c':2,'d':{'e':3}}}) == {'a':1,'b.c':2,'b.d.e':3}
assert flatten_dict({}) == {}
assert flatten_dict({'x':{'y':{'z':0}}}, sep='/') == {'x/y/z':0}
assert flatten_dict({'a':{'b':1},'c':2}) == {'a.b':1,'c':2}

assert set(top_k_frequent([1,1,1,2,2,3], 2)) == {1,2}
assert list(top_k_frequent([1], 1)) == [1]
assert len(top_k_frequent([4,1,-1,2,-1,2,3], 2)) == 2
assert set(top_k_frequent([5,5,5,5], 1)) == {5}
